const crypto = require('crypto');
const secret = $env.COPILOT_OUTBOUND_HMAC_SECRET;
if (!secret) throw new Error('COPILOT_OUTBOUND_HMAC_SECRET is required');
const headers = Object.fromEntries(Object.entries($json.headers || {}).map(([k,v]) => [k.toLowerCase(), String(v)]));
const timestamp = headers['x-acme-timestamp'];
const nonce = headers['x-acme-nonce'];
const supplied = headers['x-acme-signature'] || '';
const raw = typeof $json.rawBody === 'string' ? $json.rawBody : (typeof $json.body === 'string' ? $json.body : '');
if (!raw || !timestamp || !nonce || !/^v1=[a-f0-9]{64}$/.test(supplied)) throw new Error('invalid_signature');
if (Math.abs(Math.floor(Date.now()/1000) - Number(timestamp)) > 300) throw new Error('expired_signature');
const path = $env.COPILOT_OUTBOUND_WEBHOOK_PATH;
if (!path) throw new Error('COPILOT_OUTBOUND_WEBHOOK_PATH is required');
const digest = crypto.createHash('sha256').update(raw).digest('hex');
const base = ['v1',timestamp,nonce,'POST',path,digest].join('\n');
const expected = 'v1=' + crypto.createHmac('sha256',secret).update(base).digest('hex');
if (supplied.length !== expected.length || !crypto.timingSafeEqual(Buffer.from(supplied),Buffer.from(expected))) throw new Error('invalid_signature');
const event = JSON.parse(raw);
const keys = Object.keys(event).sort().join(',');
const resultKeys = Object.keys(event.result || {}).sort().join(',');
if (keys !== 'event_id,event_type,occurred_at,request_id,result,schema_version' || resultKeys !== 'hours,person_display_name,project_display_name,status,time_entry_id,work_date' || event.schema_version !== '1.0' || event.event_type !== 'time_entry.confirmed' || !/^[0-9a-f-]{36}$/i.test(event.event_id)) throw new Error('invalid_confirmed_event');
return [{json:{event}}];
